  if (r >= 360) r -= 360;
  const q = Math.floor(r / 90);
  const rem = r - q * 90;
  const s = sinQuarter(rem);
  const c = sinQuarter(90 - rem);
  switch (q) {
    case 0: return [s, c];
    case 1: return [c, -s];
    case 2: return [-s, -c];
