3	/** Sine of `rem` degrees for 0 ≤ rem ≤ 90, exact where it can be. */
4	function sinQuarter(rem: number): number {
5	  if (rem === 0) return 0;
6	  if (rem === 90) return 1;
7	  if (rem === 30) return 0.5;
8	  if (rem === 45) return Math.SQRT1_2;
9	  return Math.sin((rem * Math.PI) / 180);
10	}
11	
12	/**
13	 * Sine and cosine of an angle in degrees. Exact for multiples of 90° (and
14	 * for 30°/60°/45° steps where possible), and symmetric across quadrants, so
15	 * that squares and other regular figures close precisely.
16	 */
17	export function sinCosDeg(deg: number): [number, number] {
18	  let r = deg % 360;
19	  if (r < 0) r += 360;
20	  if (r >= 360) r -= 360;
21	  const q = Math.floor(r / 90);
22	  const rem = r - q * 90;
23	  const s = sinQuarter(rem);
24	  const c = sinQuarter(90 - rem);
25	  switch (q) {
26	    case 0: return [s, c];
27	    case 1: return [c, -s];
28	    case 2: return [-s, -c];
29	    default: return [-c, s];
30	  }
31	}
32	
33	/** Normalises an angle to [0, 360). */
34	export function normDeg(deg: number): number {
35	  let r = deg % 360;
36	  if (r < 0) r += 360;
37	  if (r >= 360) r -= 360;
38	  return r;
39	}
