1	import { keywordOf, nameKey, type Keyword } from './keywords';
2	import type { SourceSpan } from './errors';
3	
4	export type TokenType =
5	  | 'num' | 'name' | 'param' | 'ma' | 'str'
6	  | 'op' | 'cmp' | '[' | ']' | '(' | ')' | ','
7	  | 'comment' | 'error' | 'eof';
8	
9	export interface Token extends SourceSpan {
10	  type: TokenType;
11	  /** Raw text as written in the source. */
12	  text: string;
13	  /** Numeric value of a number literal. */
14	  value?: number;
15	  /** Normalised name (NFC, lower case) for names and `:name`. */
16	  key?: string;
17	  /** Keyword this name spells, if any. */
18	  kw?: Keyword;
19	  /** Content of a string literal (without the quotes). */
20	  str?: string;
21	  /** Whitespace (or the start/end of the text) directly before/after the token. */
22	  spaceBefore: boolean;
23	  spaceAfter: boolean;
24	  /** Message of an `error` token. */
25	  message?: string;
26	}
27	
28	const NAME_START = /[\p{L}\p{M}_]/u;
29	const NAME_CHAR = /[\p{L}\p{M}\p{N}_]/u;
30	const NUMBER_CHAR = /[\p{L}\p{M}\p{N}_.]/u;
31	const NUMBER_RE = /^(?:\d+(?:\.\d+)?|\.\d+)$/;
32	
33	function isSpace(ch: string | undefined): boolean {
34	  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r' || ch === '\f' || ch === '\v' || ch === ' ' || ch === '﻿';
35	}
36	
37	/**
38	 * Splits a source text into tokens. Never throws: malformed input becomes
39	 * `error` tokens so that the parser can report problems in source order.
40	 * Comments are included only when `withComments` is set (for highlighting).
41	 */
42	export function tokenize(src: string, withComments = false): Token[] {
43	  const tokens: Token[] = [];
44	  const n = src.length;
45	  let i = 0;
46	  let line = 1;
47	  let lineStart = 0;
48	
49	  const push = (type: TokenType, start: number, end: number, extra?: Partial<Token>): Token => {
50	    const tok: Token = {
51	      type,
52	      text: src.slice(start, end),
53	      line,
54	      col: start - lineStart + 1,
55	      offset: start,
56	      end,
57	      spaceBefore: start === 0 || isSpace(src[start - 1]),
58	      spaceAfter: end >= n || isSpace(src[end]) || src[end] === ';',
59	      ...extra,
60	    };
61	    tokens.push(tok);
62	    return tok;
63	  };
64	
65	  while (i < n) {
66	    const ch = src[i];
67	    if (ch === '\n' || ch === '\r') {
68	      if (ch === '\r' && src[i + 1] === '\n') i++;
69	      i++;
70	      line++;
71	      lineStart = i;
72	      continue;
73	    }
74	    if (isSpace(ch)) {
75	      i++;
76	      continue;
77	    }
78	    if (ch === ';') {
79	      let j = i;
80	      while (j < n && src[j] !== '\n' && src[j] !== '\r') j++;
81	      if (withComments) push('comment', i, j);
82	      i = j;
83	      continue;
84	    }
85	    const start = i;
86	    if (ch === '[' || ch === ']' || ch === '(' || ch === ')' || ch === ',') {
87	      push(ch, i, i + 1);
88	      i++;
89	      continue;
90	    }
91	    if (ch === '+' || ch === '-' || ch === '*' || ch === '/') {
92	      push('op', i, i + 1);
93	      i++;
94	      continue;
95	    }
96	    if (ch === '<' || ch === '>' || ch === '=') {
97	      let j = i + 1;
98	      if (ch === '<' && (src[j] === '=' || src[j] === '>')) j++;
99	      else if (ch === '>' && src[j] === '=') j++;
100	      push('cmp', i, j);
101	      i = j;
102	      continue;
103	    }
104	    if (ch === '"') {
105	      let j = i + 1;
106	      while (j < n && src[j] !== '"' && src[j] !== '\n' && src[j] !== '\r') j++;
107	      if (src[j] === '"') {
108	        push('str', i, j + 1, { str: src.slice(i + 1, j) });
109	        i = j + 1;
110	      } else {
111	        push('error', i, j, { message: 'Brakuje cudzysłowu zamykającego tekst. Kolor zapisz tak: "#16866a".' });
112	        i = j;
113	      }
114	      continue;
115	    }
116	    if (/[0-9.]/.test(ch)) {
117	      let j = i;
118	      while (j < n && NUMBER_CHAR.test(src[j])) j++;
119	      const text = src.slice(i, j);
120	      if (NUMBER_RE.test(text)) {
121	        const value = Number(text);
122	        if (Number.isFinite(value)) push('num', i, j, { value });
123	        else push('error', i, j, { message: `Liczba „${text}” jest za duża.` });
124	      } else {
125	        push('error', i, j, { message: `„${text}” nie jest poprawną liczbą. Liczby zapisuj cyframi, z kropką dziesiętną, np. 80, 12.5 albo .5.` });
126	      }
127	      i = j;
128	      continue;
129	    }
130	    if (NAME_START.test(ch)) {
131	      let j = i;
132	      while (j < n && NAME_CHAR.test(src[j])) j++;
133	      const text = src.slice(i, j);
134	      const key = nameKey(text);
135	      if (key === 'ma' && src[j] === ':') {
136	        push('ma', i, j + 1);
137	        i = j + 1;
138	        continue;
139	      }
140	      push('name', i, j, { key, kw: keywordOf(key) });
141	      i = j;
142	      continue;
143	    }
144	    if (ch === ':') {
145	      let j = i + 1;
146	      if (j < n && NAME_START.test(src[j])) {
147	        while (j < n && NAME_CHAR.test(src[j])) j++;
148	        const text = src.slice(i + 1, j);
149	        const key = nameKey(text);
150	        push('param', i, j, { key, kw: keywordOf(key) });
151	      } else {
152	        push('error', i, i + 1, { message: 'Po dwukropku powinna stać nazwa parametru, np. :bok.' });
153	        j = i + 1;
154	      }
155	      i = j;
156	      continue;
157	    }
158	    // Anything else is a character the language does not know.
159	    const cp = src.codePointAt(i)!;
160	    const len = cp > 0xffff ? 2 : 1;
161	    let message = `Nieznany znak „${String.fromCodePoint(cp)}”.`;
162	    if (ch === '#') {
163	      let j = i + 1;
164	      while (j < n && NAME_CHAR.test(src[j])) j++;
165	      push('error', start, j, { message: `Kolor zapisz w cudzysłowie, np. "${src.slice(i, j)}".` });
166	      i = j;
167	      continue;
168	    }
169	    if (ch === '„' || ch === '”' || ch === '“' || ch === '«' || ch === '»') {
170	      message = 'Użyj zwykłego cudzysłowu " zamiast drukarskiego.';
171	    } else if (ch === '{' || ch === '}') {
172	      message = `Nieznany znak „${ch}”. Treść powtórzeń i warunków ujmij w nawiasy kwadratowe [ ].`;
173	    } else if (ch === '!') {
174	      message = 'Nieznany znak „!”. Do porównania „różne od” użyj <>.';
175	    }
176	    push('error', i, i + len, { message });
177	    i += len;
178	  }
179	  tokens.push({
180	    type: 'eof', text: '', line, col: i - lineStart + 1, offset: n, end: n,
181	    spaceBefore: true, spaceAfter: true,
182	  });
183	  return tokens;
184	}
