15	export interface Instr {
16	  op: number;
17	  v?: number;
18	  key?: string;
19	  name?: string;
20	}
21	
22	export interface Expr {
23	  /** First token of the expression: run-time errors are reported here. */
24	  first: Token;
25	  last: Token;
26	  code: Instr[];
27	  /** True when the expression refers to a name or to `nrpowt`. */
28	  names: boolean;
29	}
