39	export type Axis = 'yaw' | 'pitch' | 'roll';
40	
41	interface Base {
42	  /** The command token (used for highlighting and for errors about the command). */
43	  tok: Token;
44	}
45	
46	export interface MoveStmt extends Base { kind: 'move'; dir: 1 | -1; arg: Expr }
47	export interface TurnStmt extends Base { kind: 'turn'; axis: Axis; sign: 1 | -1; arg: Expr }
48	export interface PenStmt extends Base { kind: 'pen'; down: boolean }
49	export interface ColorStmt extends Base { kind: 'color'; color: string }
50	export interface WidthStmt extends Base { kind: 'width'; arg: Expr }
51	export interface RepeatStmt extends Base { kind: 'repeat'; count: Expr; body: Stmt[]; close: Token }
52	export interface LetStmt extends Base { kind: 'let'; key: string; name: string; arg: Expr }
53	export interface IfStmt extends Base {
54	  kind: 'if';
55	  cond: Condition;
