30	/** Parses and validates a whole program. Throws a LogoError on the first problem. */
31	export function parse(src: string, mode: Mode): Program {
32	  if (src.length > LIMITS.sourceChars) {
33	    const at = positionOf(src, LIMITS.sourceChars);
34	    throw new LogoError(
35	      `Program jest za długi: ma ${thousands(src.length)} znaków, a limit to ${thousands(LIMITS.sourceChars)}.`,
36	      at,
37	    );
38	  }
39	  const tokens = tokenize(src).filter((t) => t.type !== 'comment');
40	  // The final token is the synthetic end-of-file marker.
41	  if (tokens.length - 1 > LIMITS.tokens) {
42	    throw new LogoError(
43	      `Program ma za dużo elementów: limit to ${thousands(LIMITS.tokens)} (słów, liczb, operatorów i nawiasów).`,
44	      tokens[LIMITS.tokens],
45	    );
46	  }
47	  return new Parser(src, tokens, mode).program();
48	}
