50	function positionOf(src: string, offset: number) {
51	  let line = 1;
52	  let lineStart = 0;
53	  for (let i = 0; i < offset; i++) {
54	    const ch = src[i];
55	    if (ch === '\n' || (ch === '\r' && src[i + 1] !== '\n')) {
56	      line++;
57	      lineStart = i + 1;
58	    }
59	  }
60	  return { line, col: offset - lineStart + 1, offset, end: offset + 1 };
61	}
