63	/** Evaluates an expression without names. Returns undefined when it fails (left for run time). */
64	export function constantValue(e: Expr): number | undefined {
65	  const st: number[] = [];
66	  for (const ins of e.code) {
67	    switch (ins.op) {
68	      case OP_NUM: st.push(ins.v!); break;
69	      case OP_NEG: st[st.length - 1] = -st[st.length - 1]; break;
70	      case OP_VAR: case OP_REP: return undefined;
71	      default: {
72	        const b = st.pop()!;
73	        const a = st.pop()!;
74	        let r: number;
75	        if (ins.op === OP_ADD) r = a + b;
76	        else if (ins.op === OP_SUB) r = a - b;
77	        else if (ins.op === OP_MUL) r = a * b;
78	        else {
79	          if (b === 0) return undefined;
80	          r = a / b;
81	        }
82	        if (!Number.isFinite(r)) return undefined;
83	        st.push(r);
84	      }
85	    }
86	  }
87	  return st[0];
88	}
