90	function levenshtein(a: string, b: string): number {
91	  const m = a.length;
92	  const n = b.length;
93	  let prev = Array.from({ length: n + 1 }, (_, j) => j);
94	  for (let i = 1; i <= m; i++) {
95	    const cur = [i];
96	    for (let j = 1; j <= n; j++) {
97	      cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
98	    }
99	    prev = cur;
100	  }
101	  return prev[n];
102	}
