110	class Parser {
111	  private i = 0;
112	  private readonly headers = new Map<number, Header>();
113	  private readonly arity = new Map<string, number>();
114	  private readonly topVars = new Set<string>();
115	  private readonly procs = new Map<string, Procedure>();
116	  private proc: ProcContext | null = null;
117	  private repDepth = 0;
118	  private brDepth = 0;
119	
120	  constructor(
121	    private readonly src: string,
122	    private readonly toks: Token[],
123	    private readonly mode: Mode,
124	  ) {
125	    this.prescan();
126	  }
127	
128	  // ---------------------------------------------------------------- helpers
129	
130	  private peek(k = 0): Token {
131	    return this.toks[Math.min(this.i + k, this.toks.length - 1)];
132	  }
133	
134	  private next(): Token {
135	    const t = this.toks[this.i];
136	    if (this.i < this.toks.length - 1) this.i++;
137	    return t;
138	  }
139	
140	  private firstOnLine(idx: number): boolean {
141	    return idx === 0 || this.toks[idx - 1].line !== this.toks[idx].line;
142	  }
143	
144	  private aloneOnLine(idx: number): boolean {
145	    const t = this.toks[idx];
146	    const after = this.toks[idx + 1];
147	    return this.firstOnLine(idx) && (after.type === 'eof' || after.line !== t.line);
148	  }
149	
150	  private fail(message: string, at: Token): never {
151	    throw new LogoError(message, at);
152	  }
153	
154	  private failToken(t: Token): never {
155	    throw new LogoError(t.message ?? `Nieoczekiwany ${show(t)}.`, t);
156	  }
157	
158	  /**
159	   * Finds procedure headers (to know arities of calls that precede definitions)
160	   * and the names assigned with `niech` at top level and in every procedure body.
161	   */
162	  private prescan(): void {
163	    const toks = this.toks;
164	    let cur: Header | null = null;
165	    for (let idx = 0; idx < toks.length - 1; idx++) {
166	      const t = toks[idx];
167	      if (t.type !== 'name') continue;
168	      if (t.kw === 'to' && cur === null && this.firstOnLine(idx)) {
169	        const nameTok = toks[idx + 1];
170	        let key: string | null = null;
171	        let arity = 0;
172	        if (nameTok.type === 'name' && !nameTok.kw && nameTok.line === t.line) {
173	          key = nameTok.key!;
174	          for (let j = idx + 2; toks[j].type !== 'eof' && toks[j].line === t.line; j++) {
175	            if (toks[j].type === 'name' || toks[j].type === 'param') arity++;
176	          }
177	          if (!this.arity.has(key)) this.arity.set(key, arity);
178	        }
179	        cur = { key, arity, vars: new Set() };
180	        this.headers.set(idx, cur);
181	        continue;
182	      }
183	      if (t.kw === 'end' && cur !== null && this.aloneOnLine(idx)) {
184	        cur = null;
185	        continue;
186	      }
187	      if (t.kw === 'let') {
188	        const n = toks[idx + 1];
189	        if ((n.type === 'name' || n.type === 'param') && !n.kw) (cur ? cur.vars : this.topVars).add(n.key!);
190	      }
191	    }
192	  }
193	
194	  // ---------------------------------------------------------------- program
195	
196	  program(): Program {
197	    const body: Stmt[] = [];
198	    for (;;) {
199	      const t = this.peek();
200	      if (t.type === 'eof') break;
201	      if (t.type === 'name' && t.kw === 'to') {
202	        if (!this.firstOnLine(this.i)) {
203	          this.fail('Słowo „oto” musi stać na początku linii: definicja procedury zaczyna się w nowej linii.', t);
204	        }
205	        this.definition();
206	        continue;
207	      }
208	      if (t.type === 'name' && t.kw === 'end') {
209	        this.fail(`Słowo „${t.text}” kończy procedurę, ale żadna procedura nie została rozpoczęta słowem „oto”.`, t);
210	      }
211	      body.push(this.statement());
212	    }
213	    return { mode: this.mode, body, procs: this.procs };
214	  }
215	
216	  private definition(): void {
217	    const otoIdx = this.i;
218	    const oto = this.next();
219	    const header = this.headers.get(otoIdx);
220	    const nameTok = this.peek();
221	    if (nameTok.type === 'eof' || nameTok.line !== oto.line) {
222	      this.fail(`Po „${oto.text}” podaj w tej samej linii nazwę procedury, np. „oto kwadrat”.`, oto);
223	    }
224	    if (nameTok.type === 'error') this.failToken(nameTok);
225	    if (nameTok.type !== 'name') {
226	      this.fail(`${show(nameTok)} nie może być nazwą procedury. Nazwa zaczyna się od litery, np. „kwadrat”.`, nameTok);
227	    }
228	    if (nameTok.kw) {
229	      this.fail(`„${nameTok.text}” to słowo języka Logo — wybierz inną nazwę procedury.`, nameTok);
230	    }
231	    const key = nameTok.key!;
232	    const existing = this.procs.get(key);
233	    if (existing) {
234	      this.fail(`Procedura „${nameTok.text}” jest już zdefiniowana w linii ${existing.nameTok.line}.`, nameTok);
235	    }
236	    this.next();
237	
238	    const params: string[] = [];
239	    const paramNames: string[] = [];
240	    const addParam = (p: Token) => {
241	      if (p.kw) this.fail(`„${p.text.replace(/^:/, '')}” to słowo języka Logo — nie może być nazwą parametru.`, p);
242	      if (params.includes(p.key!)) this.fail(`Parametr „${p.text.replace(/^:/, '')}” powtarza się w nagłówku.`, p);
243	      params.push(p.key!);
244	      paramNames.push(p.text.replace(/^:/, ''));
245	    };
246	    const sameLine = () => this.peek().type !== 'eof' && this.peek().line === oto.line;
247	
248	    if (sameLine()) {
249	      const t = this.peek();
250	      if (t.type === 'ma') {
251	        this.next();
252	        for (;;) {
253	          const p = this.peek();
254	          if (!sameLine()) {
255	            this.fail('Po „ma:” podaj w tej samej linii nazwy parametrów oddzielone przecinkami, np. „ma: bok, kąt”.', p.type === 'eof' || p.line !== oto.line ? this.toks[this.i - 1] : p);
256	          }
257	          if (p.type === 'error') this.failToken(p);
258	          if (p.type !== 'name' && p.type !== 'param') {
259	            this.fail(`${show(p)} nie może być nazwą parametru. Nazwa zaczyna się od litery, np. „bok”.`, p);
260	          }
261	          this.next();
262	          addParam(p);
263	          if (!sameLine()) break;
264	          const sep = this.peek();
265	          if (sep.type === ',') {
266	            this.next();
267	            continue;
268	          }
269	          if (sep.type === 'name' || sep.type === 'param') {
270	            this.fail('Parametry oddziel przecinkami, np. „ma: bok, kąt”.', sep);
271	          }
272	          if (sep.type === 'error') this.failToken(sep);
273	          this.fail(`Nieoczekiwany ${show(sep)} w nagłówku procedury. Treść procedury zacznij od nowej linii.`, sep);
274	        }
275	      } else if (t.type === 'param') {
276	        while (sameLine() && this.peek().type === 'param') addParam(this.next());
277	      } else if (t.type === 'name' && !t.kw) {
278	        this.fail(`Przed parametrami napisz „ma:”, np. „oto ${nameTok.text} ma: ${t.text}”.`, t);
279	      }
280	      if (sameLine()) {
281	        const extra = this.peek();
282	        if (extra.type === 'error') this.failToken(extra);
283	        this.fail(`Nieoczekiwany ${show(extra)} w nagłówku procedury. Treść procedury zacznij od nowej linii.`, extra);
284	      }
285	    }
286	
287	    const ctx: ProcContext = {
288	      key,
289	      name: nameTok.text,
290	      params: new Set(params),
291	      vars: header?.vars ?? new Set(),
292	    };
293	    const saved = { proc: this.proc, rep: this.repDepth, br: this.brDepth };
294	    this.proc = ctx;
295	    this.repDepth = 0;
296	    this.brDepth = 0;
297	    const body: Stmt[] = [];
298	    let endTok: Token;
299	    for (;;) {
300	      const t = this.peek();
301	      if (t.type === 'eof') {
302	        this.fail(`Brakuje słowa „już” kończącego procedurę „${nameTok.text}”. Napisz je samo w osobnej linii.`, oto);
303	      }
304	      if (t.type === 'name' && t.kw === 'end') {
305	        if (!this.aloneOnLine(this.i)) {
306	          this.fail(`Słowo „${t.text}” musi stać samo w osobnej linii.`, t);
307	        }
308	        endTok = this.next();
309	        break;
310	      }
311	      if (t.type === 'name' && t.kw === 'to') {
312	        this.fail(
313	          `Nie można definiować procedury wewnątrz innej procedury. Czy brakuje słowa „już” na końcu procedury „${nameTok.text}”?`,
314	          t,
315	        );
316	      }
317	      body.push(this.statement());
318	    }
319	    this.proc = saved.proc;
320	    this.repDepth = saved.rep;
321	    this.brDepth = saved.br;
322	    this.procs.set(key, { name: nameTok.text, key, params, paramNames, body, nameTok, endTok });
323	  }
