325	  // ---------------------------------------------------------------- statements
326	
327	  private statement(): Stmt {
328	    const t = this.peek();
329	    switch (t.type) {
330	      case 'error':
331	        this.failToken(t);
332	      // eslint-disable-next-line no-fallthrough
333	      case 'name':
334	        return t.kw ? this.keywordStatement(t, t.kw) : this.call(t);
335	      case 'num':
336	      case 'param':
337	      case '(':
338	        this.strayValue(t);
339	      // eslint-disable-next-line no-fallthrough
340	      case 'op':
341	        if (t.text === '+' || t.text === '-') this.strayValue(t);
342	        this.fail(`Nieoczekiwany operator „${t.text}”: w tym miejscu powinno stać polecenie.`, t);
343	      // eslint-disable-next-line no-fallthrough
344	      case 'cmp':
345	        this.fail(`Nieoczekiwany znak porównania „${t.text}”. Porównań używa się w warunkach: jeśli x > 0 [ ... ].`, t);
346	      // eslint-disable-next-line no-fallthrough
347	      case 'str':
348	        this.fail(`Nieoczekiwany tekst ${t.text}: w tym miejscu powinno stać polecenie. Kolor ustawia się poleceniem kolor ${t.text}.`, t);
349	      // eslint-disable-next-line no-fallthrough
350	      case '[':
351	        this.fail('Nieoczekiwany nawias „[”. Nawiasy kwadratowe obejmują treść polecenia powtorz, jeśli albo jeżeli.', t);
352	      // eslint-disable-next-line no-fallthrough
353	      case ']':
354	        this.fail('Nawias „]” nie ma pary — brakuje otwierającego nawiasu „[”.', t);
355	      // eslint-disable-next-line no-fallthrough
356	      case ')':
357	        this.fail('Nawias „)” nie ma pary — brakuje otwierającego nawiasu „(”.', t);
358	      // eslint-disable-next-line no-fallthrough
359	      case ',':
360	        this.fail('Nieoczekiwany przecinek. Przecinki oddzielają tylko parametry w nagłówku procedury.', t);
361	      // eslint-disable-next-line no-fallthrough
362	      case 'ma':
363	        this.fail('„ma:” może wystąpić tylko w nagłówku procedury, np. „oto kwadrat ma: bok”.', t);
364	      // eslint-disable-next-line no-fallthrough
365	      default:
366	        this.fail(`Nieoczekiwany ${show(t)}.`, t);
367	    }
368	  }
