370	  /** Reports a value standing where a command is expected. */
371	  private strayValue(t: Token): never {
372	    let text = t.text;
373	    const n = this.peek(1);
374	    if ((t.type === 'op') && n.offset === t.end && n.type !== 'eof') text += n.text;
375	    if (text.length > 24) text = text.slice(0, 24) + '…';
376	    let message = `Nieoczekiwana wartość „${text}”: w tym miejscu powinno stać polecenie.`;
377	    const prev = this.i > 0 ? this.toks[this.i - 1] : null;
378	    if (t.type === 'op' && t.spaceBefore && !t.spaceAfter && prev && isValueEnd(prev)) {
379	      message += ` Jeśli to miało być działanie, operator „${t.text}” musi mieć spacje po obu stronach albo po żadnej: „${prev.text} ${t.text} ${n.text}” lub „${prev.text}${t.text}${n.text}”.`;
380	    } else if (prev && isValueEnd(prev)) {
381	      message += ' Czy polecenie lub procedura nie dostały za dużo argumentów?';
382	    }
383	    this.fail(message, t);
384	  }
385	
386	  private keywordStatement(t: Token, kw: Keyword): Stmt {
387	    switch (kw) {
388	      case 'fd': case 'bk': {
389	        this.next();
390	        return { kind: 'move', tok: t, dir: kw === 'fd' ? 1 : -1, arg: this.argument(t) };
391	      }
392	      case 'rt': case 'lt': case 'up': case 'down': case 'rr': case 'rl': {
393	        if (COMMANDS_3D.has(kw) && this.mode === '2d') {
394	          this.fail(`Polecenie „${t.text}” działa tylko w trybie 3D. Przełącz tryb na 3D, aby obracać żółwia w przestrzeni.`, t);
395	        }
396	        this.next();
397	        const axis = kw === 'rt' || kw === 'lt' ? 'yaw' : kw === 'up' || kw === 'down' ? 'pitch' : 'roll';
398	        const sign = kw === 'rt' || kw === 'up' || kw === 'rr' ? 1 : -1;
399	        return { kind: 'turn', tok: t, axis, sign, arg: this.argument(t) };
400	      }
401	      case 'pu': case 'pd':
402	        this.next();
403	        return { kind: 'pen', tok: t, down: kw === 'pd' };
404	      case 'stop':
405	        this.next();
406	        return { kind: 'stop', tok: t };
407	      case 'home':
408	        this.next();
409	        return { kind: 'home', tok: t };
410	      case 'cs':
411	        this.next();
412	        return { kind: 'clear', tok: t };
413	      case 'color': {
414	        this.next();
415	        const c = this.peek();
416	        if (c.type === 'error') this.failToken(c);
417	        if (c.type !== 'str') {
418	          this.fail(`Po „${t.text}” podaj kolor w cudzysłowie, np. ${t.text} "#16866a".`, c.type === 'eof' ? t : c);
419	        }
420	        if (!/^#[0-9a-fA-F]{6}$/.test(c.str!)) {
421	          this.fail(`Nieprawidłowy kolor ${c.text}. Kolor zapisuje się jako "#rrggbb": krzyżyk i sześć cyfr szesnastkowych, np. "#16866a".`, c);
422	        }
423	        this.next();
424	        return { kind: 'color', tok: t, color: c.str!.toLowerCase() };
425	      }
426	      case 'width': {
427	        this.next();
428	        const arg = this.argument(t);
429	        if (!arg.names) {
430	          const v = constantValue(arg);
431	          if (v !== undefined && !(Number.isInteger(v) && v >= 1 && v <= 12)) {
432	            this.fail(widthMessage(v), arg.first);
433	          }
434	        }
435	        return { kind: 'width', tok: t, arg };
436	      }
437	      case 'repeat': {
438	        this.next();
439	        const count = this.argument(t);
440	        if (!count.names) {
441	          const v = constantValue(count);
442	          if (v !== undefined && !(Number.isInteger(v) && v >= 0 && v <= 10000)) {
443	            this.fail(repeatMessage(v), count.first);
444	          }
445	        }
446	        this.repDepth++;
447	        const { body, close } = this.block(t);
448	        this.repDepth--;
449	        return { kind: 'repeat', tok: t, count, body, close };
450	      }
451	      case 'let': {
452	        this.next();
453	        const n = this.peek();
454	        if (n.type === 'error') this.failToken(n);
455	        if (n.type !== 'name' && n.type !== 'param') {
456	          this.fail(`Po „${t.text}” podaj nazwę zmiennej i jej wartość, np. „${t.text} bok 50”.`, n.type === 'eof' ? t : n);
457	        }
458	        const plain = n.text.replace(/^:/, '');
459	        if (n.kw) this.fail(`„${plain}” to słowo języka Logo — nie może być nazwą zmiennej.`, n);
460	        const key = n.key!;
461	        if (this.arity.has(key) && !(this.proc && this.proc.params.has(key))) {
462	          this.fail(`„${plain}” to nazwa procedury — zmienna musi nazywać się inaczej.`, n);
463	        }
464	        this.next();
465	        const arg = this.argument(t, `Po „${t.text} ${plain}” podaj wartość, np. „${t.text} ${plain} 10”.`);
466	        return { kind: 'let', tok: t, key, name: plain, arg };
467	      }
468	      case 'if': case 'ifelse': {
469	        this.next();
470	        const cond = this.condition(t);
471	        const thenPart = this.block(t);
472	        if (kw === 'if') {
473	          return { kind: 'if', tok: t, cond, then: thenPart.body, thenClose: thenPart.close, else: null, elseClose: null };
474	        }
475	        const elsePart = this.block(t, true);
476	        return {
477	          kind: 'if', tok: t, cond, then: thenPart.body, thenClose: thenPart.close,
478	          else: elsePart.body, elseClose: elsePart.close,
479	        };
480	      }
481	      case 'repcount':
482	        this.fail(`„${t.text}” to wartość (numer powtórzenia), a nie polecenie. Użyj jej jako argumentu, np. „np ${t.text} * 10”.`, t);
483	      // eslint-disable-next-line no-fallthrough
484	      case 'to':
485	        this.fail('Procedury można definiować tylko na najwyższym poziomie programu, a nie wewnątrz nawiasów [ ].', t);
486	      // eslint-disable-next-line no-fallthrough
487	      case 'end':
488	        this.fail(`Słowo „${t.text}” może kończyć tylko procedurę i musi stać samo w osobnej linii.`, t);
489	    }
490	  }
