492	  private call(t: Token): Stmt {
493	    const key = t.key!;
494	    const n = this.arity.get(key);
495	    if (n === undefined) {
496	      let message = `Nieznane polecenie „${t.text}”.`;
497	      const isVar = this.proc
498	        ? this.proc.params.has(key) || this.proc.vars.has(key) || this.topVars.has(key)
499	        : this.topVars.has(key);
500	      if (isVar) {
501	        message += ` „${t.text}” to zmienna — użyj jej jako argumentu polecenia, np. „np ${t.text}”.`;
502	      } else {
503	        const suggestion = this.suggest(key);
504	        if (suggestion) message += ` Czy chodziło o „${suggestion}”?`;
505	      }
506	      this.fail(message, t);
507	    }
508	    this.next();
509	    const args: Expr[] = [];
510	    for (let k = 0; k < n; k++) {
511	      const a = this.peek();
512	      if (a.type === 'error') this.failToken(a);
513	      if (!this.canStartExpr(a)) {
514	        this.fail(
515	          `Procedura „${t.text}” wymaga ${n} ${plural(n, 'argumentu', 'argumentów', 'argumentów')}, a podano ${k}.`,
516	          a.type === 'eof' ? t : a,
517	        );
518	      }
519	      args.push(this.expression());
520	    }
521	    return { kind: 'call', tok: t, key, args };
522	  }
523	
524	  private suggest(key: string): string | null {
525	    let best: string | null = null;
526	    let bestD = Infinity;
527	    const candidates = [...ALL_SPELLINGS, ...this.arity.keys()];
528	    for (const c of candidates) {
529	      const d = levenshtein(key, c);
530	      if (d < bestD && d <= Math.max(1, Math.floor(Math.min(key.length, c.length) / 3))) {
531	        best = c;
532	        bestD = d;
533	      }
534	    }
535	    return best;
536	  }
