538	  private block(owner: Token, second = false): { body: Stmt[]; close: Token } {
539	    const open = this.peek();
540	    if (open.type === 'error') this.failToken(open);
541	    if (open.type !== '[') {
542	      const what = second
543	        ? `Polecenie „${owner.text}” wymaga dwóch części w nawiasach: [ gdy warunek jest spełniony ] [ gdy nie jest ].`
544	        : `Po „${owner.text}” brakuje nawiasu „[” z poleceniami do wykonania.`;
545	      this.fail(`${what}${open.type === 'eof' ? '' : ` Napotkano ${show(open)}.`}`, open.type === 'eof' ? owner : open);
546	    }
547	    if (this.brDepth >= LIMITS.nesting) {
548	      this.fail(`Za dużo zagnieżdżonych nawiasów [ ] (limit to ${LIMITS.nesting}).`, open);
549	    }
550	    this.next();
551	    this.brDepth++;
552	    const body: Stmt[] = [];
553	    for (;;) {
554	      const t = this.peek();
555	      if (t.type === ']') break;
556	      if (t.type === 'eof') this.fail('Brakuje nawiasu „]” zamykającego ten nawias.', open);
557	      if (t.type === 'name' && t.kw === 'end') {
558	        if (this.proc && this.aloneOnLine(this.i)) this.fail('Brakuje nawiasu „]” zamykającego ten nawias.', open);
559	        this.fail(`Słowo „${t.text}” może kończyć tylko procedurę i musi stać samo w osobnej linii.`, t);
560	      }
561	      body.push(this.statement());
562	    }
563	    const close = this.next();
564	    this.brDepth--;
565	    return { body, close };
566	  }
