570	  private canStartExpr(t: Token): boolean {
571	    switch (t.type) {
572	      case 'num': case 'param': case '(':
573	        return true;
574	      case 'name':
575	        return !t.kw || t.kw === 'repcount';
576	      case 'op':
577	        return t.text === '+' || t.text === '-';
578	      default:
579	        return false;
580	    }
581	  }
582	
583	  /** Parses one argument of `owner`, reporting a missing argument the way the rules require. */
584	  private argument(owner: Token, message?: string): Expr {
585	    const t = this.peek();
586	    if (t.type === 'error') this.failToken(t);
587	    if (!this.canStartExpr(t)) {
588	      const base = message ?? `Polecenie „${owner.text}” wymaga argumentu: liczby albo wyrażenia.`;
589	      this.fail(t.type === 'eof' ? base : `${base} Napotkano ${show(t)}.`, t.type === 'eof' ? owner : t);
590	    }
591	    return this.expression();
592	  }
593	
594	  private condition(owner: Token): Condition {
595	    const t = this.peek();
596	    if (t.type === 'error') this.failToken(t);
597	    if (!this.canStartExpr(t)) {
598	      const base = `Po „${owner.text}” podaj warunek, np. „${owner.text} x > 0 [ ... ]”.`;
599	      this.fail(t.type === 'eof' ? base : `${base} Napotkano ${show(t)}.`, t.type === 'eof' ? owner : t);
600	    }
601	    const left = this.expression();
602	    const c = this.peek();
603	    if (c.type === 'error') this.failToken(c);
604	    if (c.type !== 'cmp') {
605	      this.fail(
606	        `W warunku brakuje znaku porównania (<, >, =, <=, >=, <>). Napotkano ${show(c)}.`,
607	        c.type === 'eof' ? owner : c,
608	      );
609	    }
610	    this.next();
611	    const r = this.peek();
612	    if (r.type === 'error') this.failToken(r);
613	    if (!this.canStartExpr(r)) {
614	      this.fail(`Po znaku „${c.text}” brakuje wartości do porównania. Napotkano ${show(r)}.`, r.type === 'eof' ? c : r);
615	    }
616	    const right = this.expression();
617	    return { left, op: c.text as Comparison, right };
618	  }
619	
620	  /**
621	   * Parses an expression with an operator-precedence (shunting-yard) loop, so
622	   * deeply nested parentheses or stacked signs never exhaust the call stack.
623	   * A binary operator continues the expression only when it has whitespace on
624	   * both sides or on neither side.
625	   */
626	  private expression(): Expr {
627	    const first = this.peek();
628	    const code: Instr[] = [];
629	    const stack: StackItem[] = [];
630	    let names = false;
631	    let last = first;
632	    let prev: Token = first;
633	    let expectOperand = true;
634	    let open = 0;
635	
636	    const emit = (item: StackItem) => {
637	      if (item.kind === 'neg') code.push({ op: OP_NEG });
638	      else if (item.kind === 'bin') code.push({ op: BIN_CODE[item.op] });
639	    };
640	
641	    for (;;) {
642	      const t = this.peek();
643	      if (expectOperand) {
644	        if (t.type === 'op' && (t.text === '+' || t.text === '-')) {
645	          stack.push({ kind: t.text === '-' ? 'neg' : 'pos', tok: t });
646	          prev = this.next();
647	          continue;
648	        }
649	        if (t.type === '(') {
650	          stack.push({ kind: '(', tok: t });
651	          open++;
652	          prev = this.next();
653	          continue;
654	        }
655	        if (t.type === 'num') {
656	          code.push({ op: OP_NUM, v: t.value });
657	        } else if (t.type === 'name' && t.kw === 'repcount') {
658	          if (this.repDepth === 0) {
659	            this.fail(
660	              this.proc
661	                ? `„${t.text}” można użyć tylko wewnątrz powtorz. Tu jest w treści procedury „${this.proc.name}”, poza powtórzeniem (liczy się miejsce zapisu, nie wywołania).`
662	                : `„${t.text}” można użyć tylko wewnątrz nawiasów polecenia powtorz.`,
663	              t,
664	            );
665	          }
666	          code.push({ op: OP_REP });
667	          names = true;
668	        } else if ((t.type === 'name' && !t.kw) || t.type === 'param') {
669	          this.resolve(t);
670	          code.push({ op: OP_VAR, key: t.key, name: t.text.replace(/^:/, '') });
671	          names = true;
672	        } else {
673	          if (t.type === 'error') this.failToken(t);
674	          const at = t.type === 'eof' ? prev : t;
675	          const tail = t.type === 'eof' ? '' : ` Napotkano ${show(t)}.`;
676	          if (prev.type === '(') this.fail(`Po nawiasie „(” brakuje wartości.${tail}`, at);
677	          if (prev.type === 'op' && stack.length && stack[stack.length - 1].tok === prev && stack[stack.length - 1].kind !== 'bin') {
678	            this.fail(`Po znaku „${prev.text}” brakuje wartości.${tail}`, at);
679	          }
680	          this.fail(`Po operatorze „${prev.text}” brakuje wartości.${tail}`, at);
681	        }
682	        last = prev = this.next();
683	        expectOperand = false;
684	        continue;
685	      }
686	
687	      if (t.type === 'op' && t.spaceBefore === t.spaceAfter) {
688	        const prec = t.text === '*' || t.text === '/' ? 2 : 1;
689	        while (stack.length) {
690	          const top = stack[stack.length - 1];
691	          if (top.kind === '(' || (top.kind === 'bin' && top.prec < prec)) break;
692	          emit(stack.pop()!);
693	        }
694	        stack.push({ kind: 'bin', op: t.text, prec, tok: t });
695	        prev = this.next();
696	        expectOperand = true;
697	        continue;
698	      }
699	      if (t.type === ')' && open > 0) {
700	        while (stack[stack.length - 1].kind !== '(') emit(stack.pop()!);
701	        stack.pop();
702	        open--;
703	        last = prev = this.next();
704	        continue;
705	      }
706	      if (open > 0) {
707	        let lastOpen: Token = first;
708	        for (let k = stack.length - 1; k >= 0; k--) {
709	          if (stack[k].kind === '(') {
710	            lastOpen = stack[k].tok;
711	            break;
712	          }
713	        }
714	        if (t.type === 'error') this.failToken(t);
715	        if (this.canStartExpr(t)) {
716	          let message = `Oczekiwano operatora albo nawiasu „)”, a napotkano ${show(t)}.`;
717	          if (t.type === 'op' && t.spaceBefore !== t.spaceAfter) {
718	            message += ` Operator „${t.text}” musi mieć spacje po obu stronach albo po żadnej.`;
719	          }
720	          this.fail(message, t);
721	        }
722	        this.fail('Nawias „(” nie ma pary — brakuje zamykającego nawiasu „)”.', lastOpen);
723	      }
724	      while (stack.length) emit(stack.pop()!);
725	      return { first, last, code, names };
726	    }
727	  }
