729	  private resolve(t: Token): void {
730	    const key = t.key!;
731	    const known = this.proc
732	      ? this.proc.params.has(key) || this.proc.vars.has(key) || this.topVars.has(key)
733	      : this.topVars.has(key);
734	    if (known) return;
735	    const plain = t.text.replace(/^:/, '');
736	    if (t.kw) {
737	      this.fail(`„${plain}” to słowo języka Logo, a nie nazwa wartości.`, t);
738	    }
739	    if (this.arity.has(key)) {
740	      this.fail(`„${plain}” to nazwa procedury, a nie wartość — procedury nie zwracają wyniku.`, t);
741	    }
742	    const where = this.proc
743	      ? `parametrem procedury „${this.proc.name}” ani zmienną nadaną poleceniem niech`
744	      : 'zmienną nadaną poleceniem niech';
745	    this.fail(`Nieznana nazwa „${plain}”: nie jest ${where}.`, t);
746	  }
747	}
