71	function cmp(a: number, op: string, b: number): boolean {
72	  switch (op) {
73	    case '<': return a < b;
74	    case '>': return a > b;
75	    case '=': return a === b;
76	    case '<=': return a <= b;
77	    case '>=': return a >= b;
78	    default: return a !== b;
