82	/** Executes a parsed program. */
83	export class Machine {
84	  private ops = 0;
85	  private depth = 0;
86	  readonly log: Segment[] = [];
87	  private clearStart = 0;
88	  private readonly globals = new Map<string, number>();
89	  readonly steps: Step[] = [];
90	
91	  // Turtle state, kept in plain fields for speed.
92	  private x = 0; private y = 0; private z = 0;
93	  private hx = 0; private hy = 1; private hz = 0;
94	  private rx = 1; private ry = 0; private rz = 0;
95	  private ux = 0; private uy = 0; private uz = 1;
96	  /** While the turtle has only turned in the plane, its heading is kept as an exact angle. */
