105	  run(): Outcome {
106	    let error: LogoError | null = null;
107	    try {
108	      this.block(this.program.body, { top: true, locals: this.globals, reps: [] });
109	    } catch (e) {
110	      if (e instanceof LogoError) {
111	        e.phase = 'run';
112	        error = e;
113	      } else if (e instanceof RangeError) {
