279	  /** Evaluates an expression; every run-time problem is reported at its first token. */
280	  private value(e: Expr, frame: Frame): number {
281	    const code = e.code;
282	    if (code.length === 1 && code[0].op === OP_NUM) return code[0].v!;
283	    const st: number[] = [];
284	    for (let i = 0; i < code.length; i++) {
285	      const ins = code[i];
286	      switch (ins.op) {
287	        case OP_NUM:
288	          st.push(ins.v!);
289	          break;
290	        case OP_VAR: {
291	          let v = frame.locals.get(ins.key!);
292	          if (v === undefined && !frame.top) v = this.globals.get(ins.key!);
293	          if (v === undefined) this.fail(`Zmienna „${ins.name}” nie ma jeszcze wartości. Nadaj ją wcześniej poleceniem niech.`, e.first);
294	          st.push(v);
295	          break;
296	        }
297	        case OP_REP:
298	          st.push(frame.reps[frame.reps.length - 1]);
299	          break;
300	        case OP_NEG:
301	          st[st.length - 1] = -st[st.length - 1];
302	          break;
303	        default: {
304	          const b = st.pop()!;
305	          const a = st.pop()!;
306	          let r: number;
307	          if (ins.op === OP_ADD) r = a + b;
308	          else if (ins.op === OP_SUB) r = a - b;
309	          else if (ins.op === OP_MUL) r = a * b;
310	          else {
311	            if (b === 0) this.fail('Dzielenie przez zero.', e.first);
312	            r = a / b;
313	          }
314	          if (!Number.isFinite(r)) this.fail('Wynik działania jest zbyt duży (nieskończony).', e.first);
315	          st.push(r);
316	        }
317	      }
