330	        this.fail(`Przekroczono limit ${thousands(LIMITS.segments)} odcinków na rysunku.`, at);
331	      }
332	      this.log.push({
333	        from: [this.x + 0, this.y + 0, this.z + 0],
334	        to: [nx + 0, ny + 0, nz + 0],
335	        color: this.color,
336	        width: this.width,
337	      });
338	      drew = true;
339	    }
340	    this.x = nx;
341	    this.y = ny;
342	    this.z = nz;
343	    return drew;
344	  }
