346	  private setFlatHeading(): void {
347	    const [s, c] = sinCosDeg(this.angle);
348	    this.hx = s; this.hy = c; this.hz = 0;
349	    this.rx = c; this.ry = -s; this.rz = 0;
350	    this.ux = 0; this.uy = 0; this.uz = 1;
351	  }
352	
353	  private rotate(axis: Axis, deg: number): void {
354	    if (axis === 'yaw' && this.flat) {
355	      this.angle = normDeg(this.angle + deg);
356	      this.setFlatHeading();
357	      return;
358	    }
359	    this.flat = false;
360	    const [s, c] = sinCosDeg(deg);
361	    if (axis === 'yaw') {
362	      // Heading turns towards the right vector, around up.
363	      const hx = this.hx * c + this.rx * s, hy = this.hy * c + this.ry * s, hz = this.hz * c + this.rz * s;
364	      const rx = this.rx * c - this.hx * s, ry = this.ry * c - this.hy * s, rz = this.rz * c - this.hz * s;
365	      this.hx = hx; this.hy = hy; this.hz = hz;
366	      this.rx = rx; this.ry = ry; this.rz = rz;
367	    } else if (axis === 'pitch') {
368	      // Heading turns towards the up vector, around right.
369	      const hx = this.hx * c + this.ux * s, hy = this.hy * c + this.uy * s, hz = this.hz * c + this.uz * s;
370	      const ux = this.ux * c - this.hx * s, uy = this.uy * c - this.hy * s, uz = this.uz * c - this.hz * s;
371	      this.hx = hx; this.hy = hy; this.hz = hz;
372	      this.ux = ux; this.uy = uy; this.uz = uz;
373	    } else {
374	      // Up turns towards the right vector, around the heading.
375	      const ux = this.ux * c + this.rx * s, uy = this.uy * c + this.ry * s, uz = this.uz * c + this.rz * s;
376	      const rx = this.rx * c - this.ux * s, ry = this.ry * c - this.uy * s, rz = this.rz * c - this.uz * s;
377	      this.ux = ux; this.uy = uy; this.uz = uz;
378	      this.rx = rx; this.ry = ry; this.rz = rz;
379	    }
380	  }
381	}
