383	/** Applies one rotation to a turtle orientation (used to animate turns). */
384	export function rotateState(st: TurtleState, axis: Axis, deg: number): TurtleState {
385	  const [s, c] = sinCosDeg(deg);
386	  const { h, r, u } = st;
387	  const mix = (a: Vec3, b: Vec3, ca: number, sb: number): Vec3 => [a[0] * ca + b[0] * sb, a[1] * ca + b[1] * sb, a[2] * ca + b[2] * sb];
388	  if (axis === 'yaw') return { ...st, h: mix(h, r, c, s), r: mix(r, h, c, -s) };
389	  if (axis === 'pitch') return { ...st, h: mix(h, u, c, s), u: mix(u, h, c, -s) };
390	  return { ...st, u: mix(u, r, c, s), r: mix(r, u, c, -s) };
391	}
392	
393	export interface ExecuteOptions {
394	  trace?: boolean;
395	}
396	
397	/** Parses and runs a program. Parse-time errors draw nothing. */
398	export function execute(source: string, mode: Mode, options: ExecuteOptions = {}): Outcome {
399	  let program: Program;
400	  try {
401	    program = parse(source, mode);
402	  } catch (e) {
403	    if (e instanceof LogoError) {
404	      return { segments: [], error: e, steps: [], log: [], turtle: initialTurtle(), operations: 0 };
405	    }
406	    throw e;
407	  }
408	  return new Machine(program, options.trace ?? false).run();
409	}
