describe('comparisons', () => {
  const cases: [string, boolean][] = [
    ['2 < 3', true], ['3 < 3', false],
    ['3 > 2', true], ['3 > 3', false],
    ['3 = 3', true], ['3 = 4', false],
    ['3 <= 3', true], ['4 <= 3', false],
