    runErr(`np 10\nniech a 10000000000\nniech b -a * ${Array(31).fill('a').join(' * ')}`, 3, 9, [S([0, 0], [0, 10])]));

  // Ambiguous: for a condition, is "the argument" the whole condition or each side of the comparison?
