cat > /tmp/probe/fuzz.ts <<'EOF'
import { runPublic } from '/work/src/lang/index';
const vocab = ['np','ws','pw','lw','gora','pp','pod','opu','kolor','"#ABCDEF"','"#12"','grubosc','powtorz','niech','jeśli','jeżeli','stop','dom','czyść','nrpowt','oto','już','ma:','p','q','x','y',':x',':a','a','b',',','[',']','(',')','+','-','*','/','<','>','=','<>','<=','>=','1','2','0','.5','10','\n','\n','\n',' ',';c\n','1e3','#ff','-5','+5'];
let seed = 12345;
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
let crashes = 0;
for (let it = 0; it < 200000; it++) {
  const len = 1 + rnd(25);
  let src = '';
  for (let i = 0; i < len; i++) { const t = vocab[rnd(vocab.length)]; src += t + (rnd(3) ? ' ' : ''); }
  for (const mode of ['2d','3d'] as const) {
    try {
      const r = runPublic(src, mode);
      if (r.error && r.error.line < 1) throw new Error('bad line');
      for (const s of r.segments) for (const c of [...s.from, ...s.to]) if (!Number.isFinite(c)) throw new Error('nonfinite');
    } catch (e) {
      crashes++;
      if (crashes < 10) console.log('CRASH', JSON.stringify(src), mode, String(e));
    }
  }
}
console.log('crashes', crashes);
EOF
cd /tmp/probe && timeout 300 bun fuzz.ts

