import { chromium } from 'playwright';
const base = process.argv[2] || 'http://localhost:4173/';
const b = await chromium.launch();
const ctx = await b.newContext({ viewport: { width: 1280, height: 800 } });
const p = await ctx.newPage();
const logs = [];
p.on('console', (m) => { if (m.type() !== 'log') logs.push(`[${m.type()}] ${m.text()}`); });
p.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
await p.goto(base);
await p.waitForFunction(() => window.logomocja);
const status = () => p.locator('#editor-status').innerText();
const ta = p.locator('textarea.editor-input');

// 1. Live error marker
await ta.click();
await p.keyboard.press('Control+a');
await p.keyboard.type('np 100\npw 90\nnp foo\n');
await p.waitForTimeout(900);
console.log('live:', await status());
console.log('err mark count:', await p.locator('.tk-err-at').count(), 'gutter err:', await p.locator('.gutter-error').count());
// 2. Run with parse error -> bubble
await p.keyboard.press('Control+Enter');
await p.waitForTimeout(200);
console.log('bubble visible:', await p.locator('.error-bubble').isVisible(), await p.locator('.error-bubble').innerText());
await p.screenshot({ path: '/tmp/pw/shots/i-parse-error.png' });
// 3. runtime error keeps drawing
await p.keyboard.press('Control+a');
await p.keyboard.type('np 50\npw 90\nnp 50 / 0\n');
await p.locator('input[type=range]').fill('10');
await p.getByRole('button', { name: 'Uruchom' }).click();
await p.waitForTimeout(200);
console.log('runtime:', await status());
await p.screenshot({ path: '/tmp/pw/shots/i-runtime-error.png' });
// 4. Animated run
await p.locator('input[type=range]').fill('3');
await p.keyboard.press('Control+a');
await ta.click();
await p.keyboard.press('Control+a');
await p.keyboard.type('powtorz 6 [np 80 pw 60]\n');
await p.keyboard.press('Control+Enter');
await p.waitForTimeout(700);
console.log('running:', await status(), 'exec visible:', await p.locator('.exec-band').isVisible());
await p.screenshot({ path: '/tmp/pw/shots/i-running.png' });
await p.keyboard.press('Alt+KeyP');
await p.waitForTimeout(100);
console.log('paused:', await status());
await p.keyboard.press('Alt+KeyK');
await p.waitForTimeout(600);
console.log('after step:', await status());
await p.keyboard.press('Alt+KeyP');
await p.waitForTimeout(300);
console.log('resumed:', await status());
// edit during run
await ta.click();
await p.keyboard.press('End');
await p.keyboard.type(' ');
await p.waitForTimeout(100);
console.log('edited:', await status());
await p.keyboard.press('Alt+KeyR');
await p.waitForTimeout(100);
console.log('reset:', await status());
// Step from idle
await p.keyboard.press('Alt+KeyK');
await p.waitForTimeout(600);
await p.keyboard.press('Alt+KeyK');
await p.waitForTimeout(600);
console.log('stepped:', await status());
await p.screenshot({ path: '/tmp/pw/shots/i-stepping.png' });
// 5. Example load with dirty draft -> dialog
await p.goto(base + '#/przyklady');
await p.getByRole('button', { name: 'Otwórz przykład Gwiazda' }).click();
await p.waitForTimeout(300);
const dlg = p.locator('dialog.modal');
console.log('dialog open:', await dlg.isVisible(), await dlg.locator('h2').innerText());
await p.screenshot({ path: '/tmp/pw/shots/i-dialog.png' });
await p.getByRole('button', { name: 'Zachowaj kopię i wczytaj' }).click();
await p.waitForTimeout(500);
console.log('url after load:', p.url(), 'toast:', await p.locator('.toast').first().innerText());
// 6. share link
await p.getByRole('button', { name: 'Udostępnij' }).click();
await p.waitForTimeout(400);
const link = await p.locator('dialog input[readonly]').inputValue();
console.log('link:', link.slice(0, 90), link.length);
await p.keyboard.press('Escape');
const p2 = await ctx.newPage();
await p2.goto(link);
await p2.waitForTimeout(800);
console.log('p2 url:', p2.url(), 'editor starts:', (await p2.locator('textarea.editor-input').inputValue()).slice(0, 40));
console.log('p2 status:', await p2.locator('#editor-status').innerText());
// 7. persistence
await p2.reload();
await p2.waitForTimeout(500);
console.log('after reload:', (await p2.locator('textarea.editor-input').inputValue()).slice(0, 40));
// my programs list
await p2.goto(base + '#/przyklady');
await p2.waitForTimeout(300);
console.log('saved programs:', await p2.locator('.saved-item').count());
console.log(logs.join('\n') || 'no console warnings');
await b.close();
EOF
