cat > /tmp/probe/geo.ts <<'EOF'
import { runPublic } from '/work/src/lang/index';
type V=[number,number,number];
const cross=(a:V,b:V):V=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const dot=(a:V,b:V)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
function rot(v:V,k:V,deg:number):V{const t=deg*Math.PI/180,c=Math.cos(t),s=Math.sin(t);const kv=cross(k,v),kd=dot(k,v);return [0,1,2].map(i=>v[i]*c+kv[i]*s+k[i]*kd*(1-c)) as V;}
let seed=7;const rnd=(n:number)=>{seed=(seed*1103515245+12345)&0x7fffffff;return seed%n;};
let bad=0;
for(let it=0;it<20000;it++){
  const mode = rnd(2)?'3d':'2d';
  let p:V=[0,0,0],h:V=[0,1,0],r:V=[1,0,0],u:V=[0,0,1],pen=true,col='#16866a',w=3;
  let segs:any[]=[];const cmds:string[]=[];
  const n=1+rnd(30);
  for(let i=0;i<n;i++){
    const k=rnd(mode==='3d'?14:10);
    const a=(rnd(2)?1:-1)*[0,90,45,30,15,1,7.5,120,180,270,360,13.3,0.5][rnd(13)];
    const d=[0,1,10,25.5,100,3.3][rnd(6)]*(rnd(4)?1:-1);
    switch(k){
      case 0: case 1: cmds.push(`np ${d<0?'- '+(-d):d}`);{const q:V=[p[0]+h[0]*d,p[1]+h[1]*d,p[2]+h[2]*d];if(pen&&d!==0)segs.push({from:p,to:q,color:col,width:w});p=q;}break;
      case 2: cmds.push(`ws ${d<0?'- '+(-d):d}`);{const q:V=[p[0]-h[0]*d,p[1]-h[1]*d,p[2]-h[2]*d];if(pen&&d!==0)segs.push({from:p,to:q,color:col,width:w});p=q;}break;
      case 3: cmds.push(`pw ${a}`);h=rot(h,u,-a);r=rot(r,u,-a);break;
      case 4: cmds.push(`lw ${a}`);h=rot(h,u,a);r=rot(r,u,a);break;
      case 5: cmds.push(pen?'pod':'opu');pen=!pen;break;
      case 6: cmds.push('dom');if(pen&&(p[0]||p[1]||p[2]))segs.push({from:p,to:[0,0,0],color:col,width:w});p=[0,0,0];h=[0,1,0];r=[1,0,0];u=[0,0,1];break;
      case 7: cmds.push('czyść');segs=[];break;
      case 8: {const c='#'+rnd(0xffffff).toString(16).padStart(6,'0').toUpperCase();cmds.push(`kolor "${c}"`);col=c.toLowerCase();}break;
      case 9: {const ww=1+rnd(12);cmds.push(`grubosc ${ww}`);w=ww;}break;
      case 10: cmds.push(`gora ${a}`);h=rot(h,r,a);u=rot(u,r,a);break;
      case 11: cmds.push(`dol ${a}`);h=rot(h,r,-a);u=rot(u,r,-a);break;
      case 12: cmds.push(`pp ${a}`);u=rot(u,h,a);r=rot(r,h,a);break;
      case 13: cmds.push(`pl ${a}`);u=rot(u,h,-a);r=rot(r,h,-a);break;
    }
  }
  const src=cmds.join('\n').replace(/- /g,'-');
  const res=runPublic(src,mode as any);
  let ok=!res.error && res.segments.length===segs.length;
  if(ok) for(let i=0;i<segs.length;i++){const A=res.segments[i],B=segs[i];
    if(A.color!==B.color||A.width!==B.width||[0,1,2].some(j=>Math.abs(A.from[j]-B.from[j])>1e-7||Math.abs(A.to[j]-B.to[j])>1e-7)){ok=false;break;}}
  if(!ok){bad++; if(bad<5) console.log(mode, JSON.stringify(src), JSON.stringify(res).slice(0,300), segs.length);}
}
console.log('bad',bad);
EOF
