cat > /tmp/probe/sem.ts <<'EOF'
// Differential fuzz of run-time semantics (ops, frames, scoping, stop, nrpowt, errors) against a spec model.
import { runPublic } from '/work/src/lang/index';
let seed = Number(process.argv[2] ?? 1);
const rnd = (n: number) => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed % n; };
type E = { k: 'num'; v: number } | { k: 'var'; n: string } | { k: 'rep' } | { k: 'neg'; e: E } | { k: 'bin'; op: string; a: E; b: E } | { k: 'par'; e: E };
type S = { k: 'np' | 'pw' | 'gr' | 'let'; e: E; n?: string; line?: number } | { k: 'pod' | 'opu' | 'stop' | 'dom' | 'cs'; line?: number }
  | { k: 'rep'; e: E; body: S[]; line?: number } | { k: 'if'; a: E; op: string; b: E; t: S[]; f: S[] | null; line?: number }
  | { k: 'call'; p: number; args: E[]; line?: number };
const NP = 3;
const procParams: string[][] = [];
const procLocals: string[][] = [];
const GLOB = ['g0', 'g1'];
function genE(names: string[], inRep: boolean, d = 0): E {
  const r = rnd(d > 2 ? 3 : 8);
  if (r === 0 || (r === 1 && !names.length) || (r === 2 && !inRep)) return { k: 'num', v: rnd(5) };
  if (r === 1) return { k: 'var', n: names[rnd(names.length)] };
  if (r === 2) return { k: 'rep' };
  if (r === 3) return { k: 'neg', e: genE(names, inRep, d + 1) };
  if (r === 4) return { k: 'par', e: genE(names, inRep, d + 1) };
  return { k: 'bin', op: '+-*/'[rnd(4)], a: genE(names, inRep, d + 1), b: genE(names, inRep, d + 1) };
}
const hasNames = (e: E): boolean => e.k === 'var' || e.k === 'rep' || (e.k === 'neg' || e.k === 'par' ? hasNames(e.e) : e.k === 'bin' ? hasNames(e.a) || hasNames(e.b) : false);
function genBody(names: string[], assignable: string[], inRep: number, depth: number, len: number): S[] {
  const out: S[] = [];
  for (let i = 0; i < len; i++) {
