    const names = [...procParams[p], ...procLocals[p], ...GLOB];
    const body = genBody(names, [...procLocals[p], ...procParams[p]], 0, 0, 1 + rnd(5));
    for (const l of procLocals[p]) body.splice(rnd(body.length + 1), 0, { k: 'let', n: l, e: genE(procParams[p], false) });
    defs.push({ params: procParams[p], body });
