  const after = rnd(2) === 0;
  const emitDefs = () => defs.forEach((d, p) => { lines.push(`oto p${p}${d.params.length ? ' ma: ' + d.params.join(', ') : ''}`); serBody(d.body, '  '); lines.push('już'); });
