  let merr: Err | null = null;
  try { block(top, { top: true, vars: globals, reps: [] }); } catch (e) { if (e instanceof Err) merr = e; else throw e; }
  const res = runPublic(src, '2d');
  errs[merr ? merr.what : 'none'] = (errs[merr ? merr.what : 'none'] ?? 0) + 1;
  let ok = (merr === null) === (res.error === null);
  if (ok && merr && merr.line !== null && res.error!.line !== merr.line) ok = false;
  if (ok && res.segments.length !== segs.length) ok = false;
  if (ok) for (let i = 0; i < segs.length; i++) { const A = res.segments[i], B = segs[i];
    if (A.width !== B.width || Math.abs(A.from[0] - B.from[0]) > 1e-6 || Math.abs(A.from[1] - B.from[1]) > 1e-6 || Math.abs(A.to[0] - B.to[0]) > 1e-6 || Math.abs(A.to[1] - B.to[1]) > 1e-6) { ok = false; break; } }
