import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1280, height: 800 } });
await p.goto('http://localhost:4173/');
await p.waitForTimeout(500);
const seq = [];
for (let i = 0; i < 30; i++) {
  await p.keyboard.press('Tab');
  const d = await p.evaluate(() => {
    const e = document.activeElement;
    const name = e.getAttribute('aria-label') || e.textContent?.trim().slice(0, 25) || e.tagName;
    const cs = getComputedStyle(e);
    return `${e.tagName.toLowerCase()}:${name}${cs.outlineStyle !== 'none' && cs.outlineWidth !== '0px' ? '' : ' [NO OUTLINE]'}`;
  });
  seq.push(d);
  if (d.startsWith('textarea')) {
    // Tab inside the editor inserts indentation; Esc then Tab leaves.
    await p.keyboard.press('Tab');
    const v = await p.evaluate(() => document.activeElement.tagName);
    seq.push('  after Tab in editor still: ' + v);
    await p.keyboard.press('Escape');
  }
}
console.log(seq.join('\n'));
