await p.focus('canvas.drawing-canvas');
const before = await p.evaluate(() => document.querySelector('.drawing-info').textContent);
await p.keyboard.press('+'); await p.keyboard.press('ArrowLeft'); await p.keyboard.press('0');
console.log('canvas keys ok');
await b.close();
EOF
