import { chromium } from 'playwright';
const b = await chromium.launch();
const p = await b.newPage({ viewport: { width: 1366, height: 820 } });
await p.goto('http://localhost:4173/');
await p.waitForTimeout(500);
const prog = 'powtorz 4999 [np 3 pw 7 gora 1]';
const prog2d = 'powtorz 4999 [np nrpowt / 20 pw 7]';
for (const [src, mode] of [[prog2d, '2d'], [prog, '3d']]) {
  const t0 = Date.now();
  const r = await p.evaluate(([s, m]) => window.logomocja.open(s, m), [src, mode]);
  const t1 = Date.now();
  const paint = await p.evaluate(() => {
    const c = document.querySelector('canvas.drawing-canvas');
    const t = performance.now();
    for (let i = 0; i < 10; i++) c.dispatchEvent(new KeyboardEvent('keydown', { key: 'ArrowLeft', bubbles: true }));
    return 0;
  });
  // measure paint time by forcing synchronous paints via zoom key + rAF timing
  const frame = await p.evaluate(async () => {
    const c = document.querySelector('canvas.drawing-canvas');
    const times = [];
    for (let i = 0; i < 10; i++) {
      const t = performance.now();
      c.dispatchEvent(new KeyboardEvent('keydown', { key: i % 2 ? '+' : '-', bubbles: true }));
      await new Promise((r) => requestAnimationFrame(() => r()));
      times.push(performance.now() - t);
    }
    return times.map((x) => x.toFixed(1)).join(' ');
  });
  console.log(mode, 'segments', r.segments.length, r.error?.message ?? '', 'open ms', t1 - t0, 'frames ms', frame);
  await p.screenshot({ path: `/tmp/pw/shots/perf-${mode}.png` });
}
const runMs = await p.evaluate(() => { const t = performance.now(); window.logomocja.run('powtorz 4999 [np 3 pw 7 gora 1]', '3d'); return performance.now() - t; });
console.log('run() ms', runMs.toFixed(1));
await b.close();
