        >
          <Icon name={pref === 'system' ? 'system' : pref === 'light' ? 'sun' : 'moon'} />
        </button>
      </div>
    </header>
  );
}
import type { Mode } from '../lang/ast';

function toBase64Url(bytes: Uint8Array): string {
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(s: string): Uint8Array {
  const b64 = s.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((s.length + 3) % 4);
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

async function pipe(bytes: Uint8Array, stream: CompressionStream | DecompressionStream): Promise<Uint8Array> {
  const body = new Blob([bytes as BlobPart]).stream().pipeThrough(stream);
  return new Uint8Array(await new Response(body).arrayBuffer());
}

/** Encodes a program as a compact URL-safe string ("z…" compressed, "u…" plain UTF-8). */
export async function encodeProgram(source: string): Promise<string> {
  const raw = new TextEncoder().encode(source);
  const plain = 'u' + toBase64Url(raw);
  if (typeof CompressionStream === 'undefined') return plain;
  try {
    const packed = 'z' + toBase64Url(await pipe(raw, new CompressionStream('deflate-raw')));
    return packed.length < plain.length ? packed : plain;
  } catch {
    return plain;
  }
}

export async function decodeProgram(payload: string): Promise<string> {
  const kind = payload[0];
  const bytes = fromBase64Url(payload.slice(1));
  if (kind === 'u') return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  if (kind === 'z') {
    const out = await pipe(bytes, new DecompressionStream('deflate-raw'));
    return new TextDecoder('utf-8', { fatal: true }).decode(out);
  }
  throw new Error('Nieznany format linku.');
}

export async function permalinkFor(source: string, mode: Mode): Promise<string> {
  const payload = await encodeProgram(source);
  const base = location.href.replace(/#.*$/, '');
  return `${base}#/p/${mode}/${payload}`;
}
export function downloadBlob(blob: Blob, filename: string): void {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.rel = 'noopener';
  document.body.appendChild(a);
  a.click();
  a.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 2000);
}

export function downloadText(text: string, filename: string): void {
  downloadBlob(new Blob([text], { type: 'text/plain;charset=utf-8' }), filename);
}

/** Turns a title into a safe file name: "Drzewo 3D" → "drzewo-3d". */
export function slug(title: string): string {
  const map: Record<string, string> = { ą: 'a', ć: 'c', ę: 'e', ł: 'l', ń: 'n', ó: 'o', ś: 's', ź: 'z', ż: 'z' };
  const s = title
    .toLowerCase()
    .replace(/[ąćęłńóśźż]/g, (c) => map[c])
    .normalize('NFKD')
    .replace(/[^\w\s-]/g, '')
    .trim()
    .replace(/[\s_]+/g, '-')
    .replace(/-+/g, '-');
  return s || 'program';
}

/** Opens the system file picker and reads one text file. */
export function pickTextFile(accept = '.logo,.txt,text/plain'): Promise<{ name: string; text: string } | null> {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = accept;
    input.style.display = 'none';
    document.body.appendChild(input);
    let settled = false;
    const done = (v: { name: string; text: string } | null) => {
      if (settled) return;
      settled = true;
      input.remove();
      resolve(v);
    };
    input.addEventListener('change', async () => {
      const file = input.files?.[0];
      if (!file) return done(null);
      done({ name: file.name, text: await readFileText(file) });
    });
    input.addEventListener('cancel', () => done(null));
    input.click();
  });
}

export async function readFileText(file: File): Promise<string> {
  const buf = await file.arrayBuffer();
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(buf).replace(/^﻿/, '');
  } catch {
    // Older Polish files are often in Windows-1250.
    return new TextDecoder('windows-1250').decode(buf);
  }
}
import { computed, signal } from '@preact/signals';
import { load, save } from './storage';

export type ThemePref = 'system' | 'light' | 'dark';

const media = window.matchMedia('(prefers-color-scheme: dark)');
const systemDark = signal(media.matches);
media.addEventListener('change', (e) => {
  systemDark.value = e.matches;
});

const stored = load<string>('theme', 'system');
export const themePref = signal<ThemePref>(stored === 'light' || stored === 'dark' ? stored : 'system');
export const theme = computed<'light' | 'dark'>(() =>
  themePref.value === 'system' ? (systemDark.value ? 'dark' : 'light') : themePref.value,
);

function apply(): void {
  const root = document.documentElement;
  root.dataset.theme = theme.value;
  root.style.colorScheme = theme.value;
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute('content', theme.value === 'dark' ? '#14191b' : '#f6f2e9');
}

theme.subscribe(apply);

export function cycleTheme(): void {
  const order: ThemePref[] = ['system', 'light', 'dark'];
  themePref.value = order[(order.indexOf(themePref.value) + 1) % order.length];
  save('theme', themePref.value);
}

export function themeLabel(p: ThemePref): string {
  return p === 'system' ? 'systemowy' : p === 'light' ? 'jasny' : 'ciemny';
}
const PREFIX = 'logomocja:v1:';

/** Reads a JSON value from localStorage; never throws. */
export function load<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(PREFIX + key);
    if (raw === null) return fallback;
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

/** Writes a JSON value to localStorage; returns false when storage is unavailable or full. */
export function save(key: string, value: unknown): boolean {
  try {
    localStorage.setItem(PREFIX + key, JSON.stringify(value));
    return true;
  } catch {
    return false;
  }
}

export function remove(key: string): void {
  try {
    localStorage.removeItem(PREFIX + key);
  } catch {
    /* ignore */
  }
}

import type { ComponentChildren } from 'preact';
import { useEffect, useRef, useState } from 'preact/hooks';
import { permalinkFor } from '../state/permalink';
import { mode, source } from '../state/studio';
import { dialog, shareOpen, shortcutsOpen, toast } from '../state/ui';
import { Icon } from './icons';
import { EXTRA_SHORTCUTS, SHORTCUTS } from './shortcuts';

interface ModalProps {
  title: string;
  onClose: () => void;
  children: ComponentChildren;
  wide?: boolean;
}

/** A native modal <dialog>: traps focus, closes on Escape, restores focus afterwards. */
export function Modal({ title, onClose, children, wide }: ModalProps) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const d = ref.current!;
    const opener = document.activeElement as HTMLElement | null;
    if (!d.open) d.showModal();
    const onCancel = (e: Event) => {
      e.preventDefault();
      onClose();
    };
    d.addEventListener('cancel', onCancel);
    return () => {
      d.removeEventListener('cancel', onCancel);
      if (d.open) d.close();
      opener?.focus?.();
    };
  }, []);
  return (
    <dialog
      ref={ref}
      class={`modal${wide ? ' modal-wide' : ''}`}
      aria-labelledby="modal-title"
      onClick={(e) => {
        if (e.target === ref.current) onClose();
      }}
    >
      <div class="modal-body">
        <header class="modal-head">
          <h2 id="modal-title">{title}</h2>
          <button type="button" class="tool" onClick={onClose} aria-label="Zamknij">
            <Icon name="close" />
          </button>
        </header>
        {children}
      </div>
    </dialog>
  );
}

function AskDialog() {
  const spec = dialog.value!;
  const [text, setText] = useState(spec.input?.value ?? '');
  const inputRef = useRef<HTMLInputElement>(null);
  const primaryRef = useRef<HTMLButtonElement>(null);
  useEffect(() => {
    // Focus the text field, or else the main action (not the close button).
    const id = window.setTimeout(() => {
      if (inputRef.current) inputRef.current.select();
      else primaryRef.current?.focus();
    }, 0);
    return () => window.clearTimeout(id);
  }, []);
  const primary = spec.buttons.find((b) => b.primary) ?? spec.buttons[0];
  return (
    <Modal title={spec.title} onClose={() => spec.resolve(null)}>
      <form
        method="dialog"
        onSubmit={(e) => {
          e.preventDefault();
          spec.resolve(primary.value, text);
        }}
      >
        <p>{spec.body}</p>
        {spec.input && (
          <label class="field">
            <span>{spec.input.label}</span>
            <input ref={inputRef} type="text" value={text} maxLength={80} onInput={(e) => setText((e.currentTarget as HTMLInputElement).value)} />
          </label>
        )}
        <div class="modal-actions">
          {spec.buttons.map((b) => (
            <button
              key={b.value}
              type={b === primary ? 'submit' : 'button'}
              class={`btn${b.primary ? ' btn-primary' : ''}`}
              ref={b === primary ? primaryRef : undefined}
              onClick={b === primary ? undefined : () => spec.resolve(b.value, text)}
            >
              {b.label}
            </button>
          ))}
        </div>
      </form>
    </Modal>
  );
}

export function ShortcutList() {
  return (
    <table class="keys">
      <caption class="sr-only">Skróty klawiszowe</caption>
      <thead>
        <tr>
          <th scope="col">Klawisze</th>
          <th scope="col">Działanie</th>
        </tr>
      </thead>
      <tbody>
        {Object.values(SHORTCUTS).map((s) => (
          <tr key={s.label}>
            <td>
              <kbd>{s.label}</kbd>
            </td>
            <td>{s.description}</td>
          </tr>
        ))}
        {EXTRA_SHORTCUTS.map((s) => (
          <tr key={s.keys}>
            <td>
              <kbd>{s.keys}</kbd>
            </td>
            <td>{s.description}</td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}

function ShareDialog() {
  const [link, setLink] = useState<string>('');
  const [error, setError] = useState('');
  const inputRef = useRef<HTMLInputElement>(null);
  useEffect(() => {
    permalinkFor(source.peek(), mode.peek())
      .then((l) => {
        setLink(l);
        requestAnimationFrame(() => inputRef.current?.select());
      })
      .catch(() => setError('Nie udało się utworzyć linku.'));
  }, []);
  const copy = async () => {
    try {
      await navigator.clipboard.writeText(link);
      toast('Skopiowano link do schowka.', { tone: 'success' });
      shareOpen.value = false;
    } catch {
      inputRef.current?.select();
      toast('Nie udało się skopiować — zaznacz link i skopiuj go ręcznie.', { tone: 'error' });
    }
  };
  return (
    <Modal title="Udostępnij program" onClose={() => (shareOpen.value = false)}>
      <p>
        Link zawiera cały program i tryb {mode.peek() === '2d' ? '2D' : '3D'}. Kto go otworzy, zobaczy ten program w edytorze i od razu jego rysunek.
      </p>
      {error ? (
        <p class="form-error">{error}</p>
      ) : (
        <label class="field">
          <span>Link do programu ({link.length.toLocaleString('pl-PL')} znaków)</span>
          <input ref={inputRef} type="text" readOnly value={link} onFocus={(e) => (e.currentTarget as HTMLInputElement).select()} />
        </label>
      )}
      {link.length > 8000 && <p class="form-note">Ten link jest bardzo długi — niektóre komunikatory mogą go uciąć.</p>}
      <div class="modal-actions">
        <button type="button" class="btn btn-primary" onClick={copy} disabled={!link}>
          <Icon name="copy" /> <span>Kopiuj link</span>
        </button>
        <button type="button" class="btn" onClick={() => (shareOpen.value = false)}>
          Zamknij
        </button>
      </div>
    </Modal>
  );
}

export function DialogHost() {
  return (
    <>
      {dialog.value && <AskDialog key={dialog.value.title} />}
      {shortcutsOpen.value && (
        <Modal title="Skróty klawiszowe" onClose={() => (shortcutsOpen.value = false)} wide>
          <ShortcutList />
        </Modal>
      )}
      {shareOpen.value && <ShareDialog />}
    </>
  );
}
import { announcement, dismissToast, toasts } from '../state/ui';
import { Icon } from './icons';

export function Toasts() {
  return (
    <>
      <div class="toasts" role="region" aria-label="Powiadomienia">
        {toasts.value.map((t) => (
          <div key={t.id} class={`toast toast-${t.tone}`} role={t.tone === 'error' ? 'alert' : 'status'}>
            <span class="toast-text">{t.text}</span>
            {t.action && (
              <button
                type="button"
                class="btn btn-small"
                onClick={() => {
                  t.action!.run();
                  dismissToast(t.id);
                }}
              >
                {t.action.label}
              </button>
            )}
            <button type="button" class="tool tool-small" onClick={() => dismissToast(t.id)} aria-label="Zamknij powiadomienie">
              <Icon name="close" size={16} />
            </button>
          </div>
        ))}
      </div>
      <div class="sr-only" aria-live="polite" aria-atomic="true">
        {announcement.value}
      </div>
    </>
  );
}
import { EXAMPLES, type Example } from '../content/examples';
