import type { Mode } from '../lang/ast';
import {
  defaultCamera2D, draw2D, fitCamera2D, MAX_SCALE_2D, MIN_SCALE_2D, screenToWorld2D, type Camera2D,
} from './view2d';
import {
  defaultCamera3D, draw3D, fitCamera3D, presetAngles, type Camera3D, type CameraPreset,
} from './view3d';
import { EMPTY_SCENE, readPalette, type Palette, type Scene } from './scene';

interface PointerInfo {
  x: number;
  y: number;
}

/**
 * The interactive drawing canvas: owns the 2D and 3D cameras, handles
 * pan/zoom/orbit with mouse, touch and keyboard, and repaints on demand.
 */
export class Viewport {
  mode: Mode = '2d';
  cam2d: Camera2D = defaultCamera2D();
  cam3d: Camera3D = defaultCamera3D();
  scene: Scene = EMPTY_SCENE;
  palette: Palette;
  /** Set when the user moved the camera by hand since the last fit. */
  userAdjusted = false;
  onPaint: (() => void) | null = null;

  private readonly ctx: CanvasRenderingContext2D;
  private w = 0;
  private h = 0;
  private dpr = 1;
  private raf = 0;
  private pendingFit: Scene | null = null;
  private readonly pointers = new Map<number, PointerInfo>();
  private dragMode: 'pan' | 'orbit' = 'pan';
  private pinch: { dist: number; cx: number; cy: number } | null = null;
  private readonly ro: ResizeObserver;
  private readonly cleanup: (() => void)[] = [];

  constructor(readonly canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext('2d', { alpha: false });
    if (!ctx) throw new Error('Canvas 2D is not available');
    this.ctx = ctx;
    this.palette = readPalette();
    this.ro = new ResizeObserver(() => this.measure());
    this.ro.observe(canvas);
    this.measure();
    this.listen();
  }

  dispose(): void {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    for (const fn of this.cleanup) fn();
  }

  private on<K extends keyof HTMLElementEventMap>(type: K, fn: (e: HTMLElementEventMap[K]) => void, opts?: AddEventListenerOptions) {
    this.canvas.addEventListener(type, fn as EventListener, opts);
    this.cleanup.push(() => this.canvas.removeEventListener(type, fn as EventListener, opts));
  }

  private measure(): void {
    const rect = this.canvas.getBoundingClientRect();
    const dpr = Math.min(window.devicePixelRatio || 1, 3);
    const w = Math.max(1, Math.round(rect.width));
    const h = Math.max(1, Math.round(rect.height));
    if (w === this.w && h === this.h && dpr === this.dpr) return;
    this.w = w;
    this.h = h;
    this.dpr = dpr;
    this.canvas.width = Math.round(w * dpr);
    this.canvas.height = Math.round(h * dpr);
    if (this.pendingFit && rect.width > 0 && rect.height > 0) {
      const s = this.pendingFit;
      this.pendingFit = null;
      this.fitTo(s);
    }
    this.paintNow();
  }

  get size(): { w: number; h: number } {
    return { w: this.w, h: this.h };
  }

  setMode(mode: Mode): void {
    if (mode === this.mode) return;
    this.mode = mode;
    this.invalidate();
  }

  setScene(scene: Scene): void {
    this.scene = scene;
    this.invalidate();
  }

  refreshPalette(): void {
    this.palette = readPalette();
    this.invalidate();
  }

  /** Fits the camera so the given scene (default: the current one) is fully visible. */
  fitTo(scene: Scene = this.scene, resetAngles = false): void {
    const rect = this.canvas.getBoundingClientRect();
    if (rect.width < 2 || rect.height < 2) {
      this.pendingFit = scene;
      return;
    }
    if (this.mode === '2d') {
      const narrow = this.w < 520;
      this.cam2d = fitCamera2D(scene, this.w, this.h, undefined, {
        top: 0,
        right: narrow ? 52 : 44,
        bottom: 24,
        left: 0,
      });
    } else {
      const base = resetAngles ? { ...this.cam3d, ...presetAngles('default') } : this.cam3d;
      this.cam3d = fitCamera3D(scene, this.w, this.h, base);
    }
    this.userAdjusted = false;
    this.invalidate();
  }

  resetView(): void {
    if (this.mode === '2d') {
      this.cam2d = defaultCamera2D();
    } else {
      this.cam3d = { ...this.cam3d, ...presetAngles('default') };
      this.cam3d = fitCamera3D(this.scene, this.w, this.h, this.cam3d);
    }
    this.userAdjusted = false;
    this.invalidate();
  }

  preset(p: CameraPreset): void {
    this.cam3d = fitCamera3D(this.scene, this.w, this.h, { ...this.cam3d, ...presetAngles(p) });
    this.userAdjusted = true;
    this.invalidate();
  }

  zoom(factor: number, sx = this.w / 2, sy = this.h / 2): void {
    if (this.mode === '2d') {
      const c = this.cam2d;
      const scale = Math.min(MAX_SCALE_2D, Math.max(MIN_SCALE_2D, c.scale * factor));
      const [wx, wy] = screenToWorld2D(c, this.w, this.h, sx, sy);
      // Keep the world point under the cursor fixed.
      const cx = wx - (sx - this.w / 2) / scale;
      const cy = wy + (sy - this.h / 2) / scale;
      this.cam2d = { cx, cy, scale };
    } else {
      this.cam3d = { ...this.cam3d, dist: Math.min(2e6, Math.max(1, this.cam3d.dist / factor)) };
    }
    this.userAdjusted = true;
    this.invalidate();
  }

  /** Moves the view by a screen distance in CSS pixels. */
  pan(dx: number, dy: number): void {
    if (this.mode === '2d') {
      const c = this.cam2d;
      this.cam2d = { ...c, cx: c.cx - dx / c.scale, cy: c.cy + dy / c.scale };
    } else {
      const c = this.cam3d;
      const unit = (2 * c.dist * Math.tan((c.fov * Math.PI) / 360)) / Math.max(this.h, 1);
      const az = (c.az * Math.PI) / 180;
      const el = (c.el * Math.PI) / 180;
      const right = [-Math.sin(az), Math.cos(az), 0];
      // Screen-up direction of the camera.
      const up = [-Math.sin(el) * Math.cos(az), -Math.sin(el) * Math.sin(az), Math.cos(el)];
      const t = c.target;
      this.cam3d = {
        ...c,
        target: [
          t[0] - (dx * right[0] - dy * up[0]) * unit,
          t[1] - (dx * right[1] - dy * up[1]) * unit,
          t[2] - (dx * right[2] - dy * up[2]) * unit,
        ],
      };
    }
    this.userAdjusted = true;
    this.invalidate();
  }

  orbit(dAz: number, dEl: number): void {
    const c = this.cam3d;
    this.cam3d = { ...c, az: c.az + dAz, el: Math.max(-89.9, Math.min(89.9, c.el + dEl)) };
    this.userAdjusted = true;
    this.invalidate();
  }

  invalidate(): void {
    if (this.raf) return;
    this.raf = requestAnimationFrame(() => {
      this.raf = 0;
      this.paintNow();
    });
  }

  paintNow(): void {
    if (this.raf) {
      cancelAnimationFrame(this.raf);
      this.raf = 0;
    }
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    if (this.mode === '2d') draw2D(ctx, this.w, this.h, this.cam2d, this.scene, this.palette);
    else draw3D(ctx, this.w, this.h, this.cam3d, this.scene, this.palette);
    this.onPaint?.();
  }

  /** Renders the current view at a higher resolution and returns it as a PNG. */
  exportPNG(scale = 2): Promise<Blob | null> {
    const k = Math.max(scale, Math.min(4, 1600 / Math.max(this.w, 1)));
    const c = document.createElement('canvas');
    c.width = Math.round(this.w * k);
    c.height = Math.round(this.h * k);
    const ctx = c.getContext('2d')!;
    if (this.mode === '2d') {
      const cam = { ...this.cam2d, scale: this.cam2d.scale * k };
      draw2D(ctx, c.width, c.height, cam, { ...this.scene, turtle: null }, this.palette, { pixelScale: k });
    } else {
      draw3D(ctx, c.width, c.height, this.cam3d, { ...this.scene, turtle: null }, this.palette, { pixelScale: k });
    }
    return new Promise((resolve) => c.toBlob((b) => resolve(b), 'image/png'));
  }

  // ------------------------------------------------------------- input

  private listen(): void {
    const canvas = this.canvas;
    this.on('pointerdown', (e) => {
      canvas.setPointerCapture(e.pointerId);
      this.pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (this.pointers.size === 1) {
        const panGesture = e.button === 1 || e.button === 2 || e.shiftKey || e.ctrlKey || e.metaKey;
        this.dragMode = this.mode === '3d' && !panGesture ? 'orbit' : 'pan';
        this.pinch = null;
      } else if (this.pointers.size === 2) {
        this.pinch = this.pinchInfo();
      }
    });
    this.on('pointermove', (e) => {
      const p = this.pointers.get(e.pointerId);
      if (!p) return;
      const dx = e.clientX - p.x;
      const dy = e.clientY - p.y;
      if (this.pointers.size === 1) {
        p.x = e.clientX;
        p.y = e.clientY;
        if (this.dragMode === 'orbit') this.orbit(-dx * 0.4, dy * 0.4);
        else this.pan(dx, dy);
      } else if (this.pointers.size === 2 && this.pinch) {
        p.x = e.clientX;
        p.y = e.clientY;
        const now = this.pinchInfo();
        const rect = canvas.getBoundingClientRect();
        if (now.dist > 0 && this.pinch.dist > 0) this.zoom(now.dist / this.pinch.dist, now.cx - rect.left, now.cy - rect.top);
        this.pan(now.cx - this.pinch.cx, now.cy - this.pinch.cy);
        this.pinch = now;
      }
    });
    const end = (e: PointerEvent) => {
      this.pointers.delete(e.pointerId);
      if (this.pointers.size < 2) this.pinch = null;
      if (this.pointers.size === 1) {
        // Continue with the remaining finger without a jump.
        this.dragMode = this.mode === '3d' ? 'orbit' : 'pan';
      }
    };
    this.on('pointerup', end);
    this.on('pointercancel', end);
    this.on('lostpointercapture', end);
    this.on('contextmenu', (e) => e.preventDefault());
    this.on('dblclick', () => this.fitTo());
    this.on('wheel', (e) => {
      e.preventDefault();
      const unit = e.deltaMode === 1 ? 16 : e.deltaMode === 2 ? 400 : 1;
      const delta = e.deltaY * unit;
      const factor = Math.exp(-delta * (e.ctrlKey ? 0.01 : 0.0015));
      const rect = canvas.getBoundingClientRect();
      this.zoom(factor, e.clientX - rect.left, e.clientY - rect.top);
    }, { passive: false });
    this.on('keydown', (e) => {
      if (e.altKey || e.ctrlKey || e.metaKey) return;
      const step = 40;
      let handled = true;
      switch (e.key) {
        case 'ArrowLeft':
          if (this.mode === '3d' && !e.shiftKey) this.orbit(5, 0); else this.pan(step, 0);
          break;
        case 'ArrowRight':
          if (this.mode === '3d' && !e.shiftKey) this.orbit(-5, 0); else this.pan(-step, 0);
          break;
        case 'ArrowUp':
          if (this.mode === '3d' && !e.shiftKey) this.orbit(0, -5); else this.pan(0, step);
          break;
        case 'ArrowDown':
          if (this.mode === '3d' && !e.shiftKey) this.orbit(0, 5); else this.pan(0, -step);
          break;
        case '+': case '=':
          this.zoom(1.25);
          break;
        case '-': case '_':
          this.zoom(0.8);
          break;
        case '0': case 'f': case 'F':
          this.fitTo();
          break;
        default:
          handled = false;
      }
      if (handled) e.preventDefault();
    });
  }

  private pinchInfo(): { dist: number; cx: number; cy: number } {
    const [a, b] = [...this.pointers.values()];
    return { dist: Math.hypot(a.x - b.x, a.y - b.y), cx: (a.x + b.x) / 2, cy: (a.y + b.y) / 2 };
  }
}
import type { SourceSpan } from '../lang/errors';
import { initialTurtle, rotateState, type Outcome, type Segment, type Step, type TurtleState } from '../lang/interpreter';
import type { Scene } from '../render/scene';

export const SPEED_MIN = 1;
export const SPEED_MAX = 10;
/** Speed factors for levels 1–9; level 10 draws instantly. */
const FACTORS = [0.3, 0.55, 1, 1.8, 3.2, 6, 12, 28, 80];

export function speedLabel(level: number): string {
  if (level >= SPEED_MAX) return 'natychmiast';
  if (level <= 2) return 'bardzo wolno';
  if (level <= 4) return 'wolno';
  if (level <= 6) return 'średnio';
  if (level <= 8) return 'szybko';
  return 'bardzo szybko';
}

export interface PlayerView {
  scene: Scene;
  /** Source position of the operation shown (in progress or just finished). */
  at: SourceSpan | null;
  /** Number of completed steps and the total. */
  done: number;
  total: number;
}

function lerp(a: readonly number[], b: readonly number[], t: number): [number, number, number] {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

/**
 * Plays back a recorded run: steps are animated with durations that depend on
 * the distance moved or the angle turned, scaled by the speed level.
 */
export class Player {
  outcome: Outcome | null = null;
  /** Number of fully completed steps. */
  index = 0;
  /** Seconds spent in the current (index-th) step. */
  progress = 0;
  playing = false;
  speed = 6;
  ghost: readonly Segment[] | null = null;
  private stepUntil = -1;
  private raf = 0;
  private last = 0;

  constructor(
    private readonly onFrame: (view: PlayerView) => void,
    private readonly onEnd: () => void,
  ) {}

  get steps(): Step[] {
    return this.outcome?.steps ?? [];
  }

  get finished(): boolean {
    return !!this.outcome && this.index >= this.steps.length;
  }

  get started(): boolean {
    return this.index > 0 || this.progress > 0;
  }

  load(outcome: Outcome): void {
    this.halt();
    this.outcome = outcome;
    this.index = 0;
    this.progress = 0;
    this.stepUntil = -1;
  }

  clear(): void {
    this.halt();
    this.outcome = null;
    this.index = 0;
    this.progress = 0;
  }

  play(): void {
    if (!this.outcome) return;
    this.stepUntil = -1;
    if (this.speed >= SPEED_MAX) {
      this.toEnd();
      return;
    }
    this.start();
  }

  /** Advances by one operation (finishing the current one if it is half-drawn). */
  step(): void {
    if (!this.outcome || this.finished) return;
    if (this.progress > 0) {
      this.halt();
      this.index++;
      this.progress = 0;
      this.emit();
      if (this.finished) this.onEnd();
      return;
    }
    this.stepUntil = this.index + 1;
    this.start();
  }

  pause(): void {
    this.halt();
    this.emit();
  }

  toEnd(): void {
    this.halt();
    if (!this.outcome) return;
    this.index = this.steps.length;
    this.progress = 0;
    this.emit();
    this.onEnd();
  }

  /** Stops the animation loop and leaves the current frame as it is. */
  halt(): void {
    this.playing = false;
    if (this.raf) cancelAnimationFrame(this.raf);
    this.raf = 0;
  }

  private start(): void {
    this.halt();
    this.playing = true;
    this.last = performance.now();
    this.raf = requestAnimationFrame((t) => this.tick(t));
  }

  private duration(i: number): number {
    const steps = this.steps;
    const s = steps[i];
    const prev = i > 0 ? steps[i - 1].state : initialTurtle();
    let base: number;
    if (s.turn) {
      base = 0.1 + Math.min(Math.abs(s.turn.deg), 720) / 540;
    } else {
      const d = Math.hypot(s.state.pos[0] - prev.pos[0], s.state.pos[1] - prev.pos[1], s.state.pos[2] - prev.pos[2]);
      base = d > 0 ? 0.12 + Math.min(d, 800) / 220 : 0.12;
    }
    const level = Math.max(SPEED_MIN, Math.min(SPEED_MAX - 1, Math.round(this.speed)));
    let dur = base / FACTORS[level - 1];
    if (this.stepUntil >= 0) dur = Math.min(dur, 0.35);
    return dur;
  }

  private tick(now: number): void {
    this.raf = 0;
    if (!this.playing || !this.outcome) return;
    let budget = Math.min(0.1, (now - this.last) / 1000);
    this.last = now;
    const steps = this.steps;
    while (budget > 0 && this.index < steps.length) {
      if (this.stepUntil >= 0 && this.index >= this.stepUntil) break;
      const remain = this.duration(this.index) - this.progress;
      if (budget >= remain) {
        budget -= remain;
        this.index++;
        this.progress = 0;
      } else {
        this.progress += budget;
        budget = 0;
      }
    }
    this.emit();
    if (this.index >= steps.length) {
      this.halt();
      this.onEnd();
      return;
    }
    if (this.stepUntil >= 0 && this.index >= this.stepUntil) {
      this.stepUntil = -1;
      this.halt();
      this.onFrame(this.view());
      return;
    }
    this.raf = requestAnimationFrame((t) => this.tick(t));
  }

  emit(): void {
    this.onFrame(this.view());
  }

  view(): PlayerView {
    const out = this.outcome;
    if (!out) {
      return { scene: { log: [], start: 0, end: 0, partial: null, turtle: initialTurtle(), ghost: this.ghost }, at: null, done: 0, total: 0 };
    }
    const steps = out.steps;
    const i = this.index;
    const base = i > 0 ? steps[i - 1] : null;
    const baseState: TurtleState = base ? base.state : initialTurtle();
    let turtle = baseState;
    let partial: Segment | null = null;
    let at: SourceSpan | null = base ? base.at : null;
    if (i < steps.length && this.progress > 0) {
      const cur = steps[i];
      const t = Math.min(1, this.progress / this.duration(i));
      at = cur.at;
      turtle = { ...cur.state, pos: lerp(baseState.pos, cur.state.pos, t), h: baseState.h, r: baseState.r, u: baseState.u };
      if (cur.turn) {
        const turned = rotateState(baseState, cur.turn.axis, cur.turn.deg * t);
        turtle = { ...turtle, h: turned.h, r: turned.r, u: turned.u };
      }
      if (cur.drew) {
        const seg = out.log[cur.segEnd - 1];
        partial = { ...seg, to: lerp(seg.from, seg.to, t) };
      }
    } else if (i >= steps.length && steps.length === 0) {
      turtle = out.turtle;
    }
    return {
      scene: {
        log: out.log,
        start: base ? base.clearStart : 0,
        end: base ? base.segEnd : 0,
        partial,
        turtle,
        ghost: this.ghost,
      },
      at,
      done: i,
      total: steps.length,
    };
  }
}

