  border-bottom: 0;
  border-top: 6px solid var(--danger);
}

:root[data-theme='dark'] .error-bubble-above::before {
  border-top-color: #8f2622;
}

:root[data-theme='dark'] .error-bubble::before {"""
assert old in s
s=s.replace(old,new,1)
open(p,'w').write(s)
