const status = () => p.locator('#editor-status').innerText();
const ta = p.locator('textarea');
// 1
await ta.click(); await p.keyboard.press('Control+a'); await p.keyboard.type('np 10 / 0');
await p.keyboard.press('Alt+KeyK'); await p.waitForTimeout(200);
console.log('1:', (await status()).replace(/\n/g, ' '));
// 3 reveal horizontally
const long = 'np 20\n' + 'pw 1 np 1 '.repeat(40) + 'np 5 / 0';
await p.evaluate((s) => window.logomocja.open(s, '2d'), long);
await p.locator('.status-link').click(); await p.waitForTimeout(200);
console.log('3: scrollLeft', await p.evaluate(() => document.querySelector('textarea').scrollLeft));
// 4 bubble visible after reveal
console.log('4: bubble box', await p.evaluate(() => { const b = document.querySelector('.error-bubble'); const r = b.getBoundingClientRect(); const e = document.querySelector('.editor-main').getBoundingClientRect(); return [Math.round(r.left), Math.round(r.right), Math.round(e.left), Math.round(e.right), b.hidden]; }));
await p.screenshot({ path: '/tmp/pw/shots/fix-reveal.png', clip: { x: 0, y: 140, width: 560, height: 300 } });
// 5 exec follow horizontally
await p.evaluate((s) => window.logomocja.open(s, '2d'), 'np 20\n' + 'pw 1 np 1 '.repeat(30));
await p.keyboard.press('Alt+KeyR');
for (let i = 0; i < 30; i++) { await p.keyboard.press('Alt+KeyK'); await p.waitForTimeout(60); }
await p.waitForTimeout(400);
console.log('5: exec box in view', await p.evaluate(() => { const b = document.querySelector('.exec-box').getBoundingClientRect(); const e = document.querySelector('.editor-main').getBoundingClientRect(); return b.left >= e.left && b.right <= e.right; }));
// 6 Ctrl+Enter in a dialog
await p.getByRole('button', { name: 'Zapisz', exact: true }).click(); await p.waitForTimeout(200);
await p.keyboard.press('Control+Enter'); await p.waitForTimeout(200);
console.log('6: status', (await status()).slice(0, 40), '| dialog open:', await p.locator('dialog[open]').count());
await p.keyboard.press('Escape');
// 2 challenge layout
await p.goto('http://localhost:4173/#/wyzwanie/domek'); await p.waitForTimeout(400);
await p.getByRole('button', { name: 'Sprawdź' }).click(); await p.waitForTimeout(400);
console.log('2: doc height', await p.evaluate(() => document.documentElement.scrollHeight), 'viewport 800');
await p.screenshot({ path: '/tmp/pw/shots/fix-challenge.png' });
const p2 = await b.newPage({ viewport: { width: 1000, height: 700 } });
await p2.goto('http://localhost:4173/#/wyzwanie/wieza'); await p2.waitForTimeout(400);
console.log('2b: doc height', await p2.evaluate(() => document.documentElement.scrollHeight), 'viewport 700');
await p2.screenshot({ path: '/tmp/pw/shots/fix-challenge-1000.png' });
// już dedent
await p.goto('http://localhost:4173/'); await p.waitForTimeout(300);
await ta.click(); await p.keyboard.press('Control+a'); await p.keyboard.type('oto f\n');
await p.keyboard.type('np 10\njuż');
console.log('już:', JSON.stringify(await ta.inputValue()));
console.log('errors:', errs.length ? errs : 'none');
await b.close();
EOF
source /tmp/pw/env.sh && cd /tmp/pw && timeout 120 node qafix.mjs

